package com.clara.memory.semantic.api;
import java.nio.file.Path;
public final class SemanticMemoryStoreConfig {private final Path workspace;private final String workspaceId,embeddingModel,embeddingRevision;private final int dimension,maxEntries,snapshotAfterOperations,maxContentChars;private final SemanticMemoryDurability durability;private final SemanticMemoryEviction eviction;
 public SemanticMemoryStoreConfig(Path workspace,String workspaceId,String model,String revision,int dimension,int maxEntries,int snapshotAfter,int maxContentChars,SemanticMemoryDurability durability,SemanticMemoryEviction eviction){if(workspace==null||!workspace.isAbsolute()||blank(workspaceId)||blank(model)||blank(revision)||dimension<=0||maxEntries<=0||snapshotAfter<=0||maxContentChars<=0||durability==null||eviction==null)throw new IllegalArgumentException("semantic memory config is invalid");this.workspace=workspace.normalize();this.workspaceId=workspaceId;embeddingModel=model;embeddingRevision=revision;this.dimension=dimension;this.maxEntries=maxEntries;snapshotAfterOperations=snapshotAfter;this.maxContentChars=maxContentChars;this.durability=durability;this.eviction=eviction;}
 public Path getWorkspace(){return workspace;}public String getWorkspaceId(){return workspaceId;}public String getEmbeddingModel(){return embeddingModel;}public String getEmbeddingRevision(){return embeddingRevision;}public int getDimension(){return dimension;}public int getMaxEntries(){return maxEntries;}public int getSnapshotAfterOperations(){return snapshotAfterOperations;}public int getMaxContentChars(){return maxContentChars;}public SemanticMemoryDurability getDurability(){return durability;}public SemanticMemoryEviction getEviction(){return eviction;}private static boolean blank(String v){return v==null||v.trim().isEmpty();}}
